%% =====================================================================
%  mc_02 : Monte Carlo robustness screening -- closed-loop short-period
%  ---------------------------------------------------------------------
%  Elevator state-feedback loop u = -K*x on the nominal longitudinal model
%  x = [u, w, q, theta]^T,  xdot = A*x + B*delta_e.
%  K places the NOMINAL closed-loop short-period at
%       omega_n = 2.1 rad/s, zeta = 0.55  (phugoid held at open-loop).
%  Mw, Zw, Mq uncertain by +/-20% (independent uniform box).
%  N = 200 deterministic samples (seeded rng), pass spec per sample:
%       short-period omega_n in [2.0, 2.2] rad/s  AND  zeta >= 0.52.
%  Writes result.json (jsonencode) with keys:
%       pass_fraction, failing_case_count
%  =====================================================================

%% ------------------- nominal longitudinal model ----------------------
Vn  = 740.0;
Xu  = -0.006;    Xw  = 0.033;
Zu  = -0.027;    Zw0 = -0.66;
Mw0 = -0.0046;   Mq0 = -0.78;
g0  = 32.174;

A = [ Xu,   Xw,   0,    -g0 ;
      Zu,   Zw0,  Vn,    0  ;
      0,    Mw0,  Mq0,   0  ;
      0,    0,    1,     0  ];

B = [0; -5.5; -4.5; 0];

%% ---------- state-feedback gain (SP placed, phugoid open-loop) --------
lam_ol = eig(A);
[~, idx] = sort(abs(lam_ol));            % two slowest = phugoid pair
ph = lam_ol(idx(1:2));
if any(abs(imag(ph)) > 0)                % enforce an exact conjugate pair
    p_ph = [real(ph(1)) + 1i*abs(imag(ph(1)));
            real(ph(1)) - 1i*abs(imag(ph(1)))];
else
    p_ph = real(ph(:));
end

wn_d  = 2.1;                             % desired short-period
zt_d  = 0.55;
re_d  = -zt_d*wn_d;
im_d  =  wn_d*sqrt(1 - zt_d^2);
p_des = [p_ph(1); p_ph(2); re_d + 1i*im_d; re_d - 1i*im_d];

assert(rank(ctrb(A,B)) == 4, '(A,B) is not controllable');
K = place(A, B, p_des);                  % 1x4 gain, u = -K*x

% quick verification of the nominal design (informational)
lam_nom  = eig(A - B*K);
[~, ordN] = sort(abs(lam_nom));
spN      = lam_nom(ordN(3:4));
wnN      = sqrt(real(spN(1)*spN(2)));
ztN      = -real(spN(1) + spN(2))/(2*wnN);
fprintf('Nominal closed-loop short-period: wn = %.4f rad/s, zeta = %.4f\n', wnN, ztN);

%% ------------------------- Monte Carlo loop --------------------------
N   = 200;
pct = 0.20;

rng(20260828); f_Mw = 1 + pct*(2*rand(N,1) - 1);   % Mw multipliers
rng(20261828); f_Zw = 1 + pct*(2*rand(N,1) - 1);   % Zw multipliers
rng(20262828); f_Mq = 1 + pct*(2*rand(N,1) - 1);   % Mq multipliers

wn_lo   = 2.0;
wn_hi   = 2.2;
zeta_lo = 0.52;

count = 0;
for i = 1:N
    Ai = A;
    Ai(3,2) = Mw0 * f_Mw(i);            % perturbed Mw
    Ai(2,2) = Zw0 * f_Zw(i);            % perturbed Zw
    Ai(3,3) = Mq0 * f_Mq(i);            % perturbed Mq

    lam = eig(Ai - B*K);                % closed-loop poles, sample i

    % short-period = the two fastest (largest |lambda|) closed-loop poles
    [~, ord] = sort(abs(lam));
    sp = lam(ord(3:4));

